from __future__ import annotations

import re
import subprocess
import sys
import unicodedata
import unittest
from pathlib import Path

import ledgerlock
from ledgerlock import ConflictError, Ledger
from ledgerlock.format import normalize_key

ROOT = Path(__file__).resolve().parent.parent
PACKAGE = ROOT / "ledgerlock"

FORBIDDEN_IMPORT = re.compile(
    r"^(import|from)\s+(socket|subprocess|requests|http|urllib|asyncio|ssl|multiprocessing|ctypes|http\.server|http\.client|socketserver)\b"
)
FORBIDDEN_CALL = re.compile(r"os\.system|subprocess\.|socket\.")


class TestNormalizeKey(unittest.TestCase):
    def test_returns_nfc_normalized_bytes(self):
        samples = [
            "",
            "plain ascii",
            "\u00e9",
            "e\u0301",
            "\u03a9",
            "\u03a9\u0301",
            "\U0001f600",
            "mixed \u00e9 and \u65e5\u672c\u8a9e",
        ]
        for s in samples:
            with self.subTest(s=s):
                self.assertEqual(normalize_key(s), unicodedata.normalize("NFC", s))

    def test_nfc_and_nfd_forms_collapse(self):
        nfc = "\u00e9"
        nfd = "e\u0301"
        self.assertEqual(normalize_key(nfc), nfc)
        self.assertEqual(normalize_key(nfd), nfc)
        self.assertEqual(normalize_key(nfc), normalize_key(nfd))


class TestPackageImport(unittest.TestCase):
    def test_import_prints_init_path(self):
        self.assertTrue(ledgerlock.__file__.endswith("__init__.py"))

    def test_top_level_names_exported(self):
        self.assertIs(Ledger, ledgerlock.Ledger)
        self.assertIs(ConflictError, ledgerlock.ConflictError)

    def test_ledger_is_callable_class(self):
        self.assertTrue(isinstance(Ledger, type))
        self.assertTrue(callable(Ledger))

    def test_conflict_error_is_exception(self):
        self.assertTrue(issubclass(ConflictError, Exception))


class TestNoSideChannels(unittest.TestCase):
    def _source_lines(self):
        lines = []
        for path in sorted(PACKAGE.rglob("*.py")):
            lines.extend(path.read_text(encoding="utf-8").splitlines())
        return lines

    def test_no_forbidden_imports(self):
        for line in self._source_lines():
            self.assertIsNone(FORBIDDEN_IMPORT.search(line), line)

    def test_no_forbidden_calls(self):
        for line in self._source_lines():
            self.assertIsNone(FORBIDDEN_CALL.search(line), line)


class TestCliUsageError(unittest.TestCase):
    def test_verify_extra_positional_exits_2_empty_stdout(self):
        result = subprocess.run(
            [sys.executable, "-m", "ledgerlock", "verify", "ledger.jsonl", "extra"],
            cwd=ROOT,
            capture_output=True,
            check=False,
        )
        self.assertEqual(result.returncode, 2)
        self.assertEqual(result.stdout, b"")


if __name__ == "__main__":
    unittest.main()

