    op = operation[0]
    if op == "put":
        if len(operation) != 5:
            raise ValueError("put requires (op, key, value, rid, ts)")
        _, raw_key, value, rid, ts = operation
        fields = {"op": "put", "key": None, "value": value, "ts": ts, "id": rid}
    elif op == "delete":
        if len(operation) != 4:
            raise ValueError("delete requires (op, key, rid, ts)")
        _, raw_key, rid, ts = operation
        fields = {"op": "delete", "key": None, "ts": ts, "id": rid}
    else:
        raise ValueError(f"unknown op: {op!r}")

    key = fmt.normalize_key(raw_key)
    if key == "":
        raise ValueError("empty key")

    fields["key"] = key
    return key, rid, fields


def _read_lines(path):
    try:
        return store.read_lines(path)
    except FileNotFoundError:
        return []


def _load_index(path):
    """Return (key_map, tail_hash) for the ledger on disk.

    key_map maps each NFC-normalized key to its most recent committed line
    dict (including tombstones). tail_hash is the chain head hash, or GENESIS
    when the ledger is empty.
    """
    key_map = {}
    tail = fmt.GENESIS
    for raw in _read_lines(path):
        line = json.loads(raw.decode("utf-8"))
        key_map[fmt.normalize_key(line["key"])] = line
        tail = line["hash"]
    return key_map, tail


