    key, rid, fields = _parse_operation(operation)

    key_map, prev_hash = _load_index(ledger.path)
    committed = key_map.get(key)
    if committed is not None:
        if committed["id"] == rid:
            result = dict(committed)
            result["replayed"] = True
            result["committed"] = False
            return result
        raise ConflictError(
            key=key,
            incoming_rid=rid,
            committed_rid=committed["id"],
            batch_index=None,
        )

    fields["prev_hash"] = prev_hash
    fields["hash"] = fmt.line_hash(prev_hash, fields)

    _append_bytes(ledger.path, _line_bytes(fields))

    fields["replayed"] = False
    fields["committed"] = True
