    state = {}
    for raw in _read_lines(ledger.path):
        try:
            line = json.loads(raw.decode("utf-8"))
        except (UnicodeDecodeError, json.JSONDecodeError):
            break
        key = fmt.normalize_key(line["key"])
        if line["op"] == "put":
            state[key] = line["value"]
        elif line["op"] == "delete":
            state.pop(key, None)
    return {key: state[key] for key in sorted(state)}


